async function PICK_ONE(tbl) {
  let length = 0, cnt = 0, rnd = 0, msg = 0, rfrob = 0;
  length = get(tbl, 0);
  cnt = get(tbl, 1);
  length = length - 1;
  tbl = tbl + 2;
  rfrob = tbl + (cnt * 2);
  rnd = random(length - cnt);
  msg = get(rfrob, rnd);
  put(rfrob, rnd, get(rfrob, 1));
  put(rfrob, 1, msg);
  cnt = cnt + 1;
  if (cnt == length) {
    cnt = 0;
  }
  put(tbl, 0, cnt);
  return msg;
}

async function DPRINT(obj) {
  if (obj == SULTANS_WIFE) {
    tell("Sultan");
    if (g.MALE) {
      tell("'s wife #");
    } else {
      tell("ess' husband #");
    }
    return printN(g.CHOICE_NUMBER);
  } else if (hasFlag(obj, UNTEEDBIT)) {
    tell(S(getProp(obj, P.NO_T_DESC)));
    return true;
  } else if (getProp(obj, P.SDESC)) {
    tell(S(getProp(obj, P.SDESC)));
    return true;
  } else {
    return printD(obj);
  }
}

