async function GO() {
  restart: for (;;) {
    g.HERE = WARNING;
    tell("   Some material in this story may not be suitable for children, especially the parts involving sex, which no one should know anything about until reaching the age of eighteen (twenty-one in certain states). This story is also unsuitable for censors, members of the Moral Majority, and anyone else who thinks that sex is dirty rather than fun.\n   The attitudes expressed and language used in this story are representative only of the views of the author, and in no way represent the views of Infocom, Inc. or its employees, many of whom are children, censors, and members of the Moral Majority. (But very few of whom, based on last year's Christmas Party, think that sex is dirty.)\n   By now, all the folks who might be offended by ", S(g.LGOP_CAPS), " have whipped their disk out of their drive and, evidence in hand, are indignantly huffing toward their dealer, their lawyer, or their favorite repression-oriented politico. So..", S(g.HIT_RETURN), "begin!");
    await read(g.P_INBUF, g.P_LEXV);
    await CLEAR_SCREEN();
    g.WINNER = PROTAGONIST;
    g.HERE = JOES_BAR;
    tell("The place: Upper Sandusky, Ohio. The time: 1936. The beer: at a nickel a mug, you don't ask for brand names. All you know is that your fifth one tasted as bad as the first.\n\n");
    await V_VERSION();
    crlf();
    await V_LOOK();
    await I_URGE();
    await MAIN_LOOP();
    continue restart;
  }
}

async function CLEAR_SCREEN() {
  let cnt = 24;
  for (;;) {
    crlf();
    cnt = cnt - 1;
    if (cnt == 0) {
      return true;
    }
  }
}

async function MAIN_LOOP() {
  let trash = 0;
  for (;;) {
    trash = await MAIN_LOOP_1();
  }
}

async function MAIN_LOOP_1() {
  let icnt = 0, ocnt = 0, num = 0, cnt = 0, obj = 0, tbl = 0, v_ = 0, ptbl = 0, obj1 = 0, tmp = 0;
  cnt = 0;
  obj = false;
  ptbl = true;
  if (g.P_WON = await PARSER()) {
    icnt = get(g.P_PRSI, g.P_MATCHLEN);
    ocnt = get(g.P_PRSO, g.P_MATCHLEN);
    if (g.P_IT_OBJECT && (await ACCESSIBLE$(g.P_IT_OBJECT))) {
      tmp = false;
      loop1: for (;;) {
        if ((cnt = cnt + 1) > icnt) {
          break loop1;
        } else {
          if (eq(get(g.P_PRSI, cnt), IT)) {
            if (await TOO_DARK_FOR_IT$()) {
              return true;
            }
            put(g.P_PRSI, cnt, g.P_IT_OBJECT);
            tmp = true;
            break loop1;
          }
        }
      }
      if (!tmp) {
        cnt = 0;
        loop2: for (;;) {
          if ((cnt = cnt + 1) > ocnt) {
            break loop2;
          } else {
            if (eq(get(g.P_PRSO, cnt), IT)) {
              if (await TOO_DARK_FOR_IT$()) {
                return true;
              }
              put(g.P_PRSO, cnt, g.P_IT_OBJECT);
              break loop2;
            }
          }
        }
      }
      cnt = 0;
    }
    num = ocnt == 0 ? ocnt : (ocnt > 1 ? (tbl = g.P_PRSO, icnt == 0 ? (obj = false) : (obj = get(g.P_PRSI, 1)), ocnt) : (icnt > 1 ? (ptbl = false, tbl = g.P_PRSI, obj = get(g.P_PRSO, 1), icnt) : 1));
    if (!obj && (icnt == 1)) {
      obj = get(g.P_PRSI, 1);
    }
    if (g.PRSA == V.WALK) {
      v_ = await PERFORM_PRSA(g.PRSO);
    } else if (num == 0) {
      if ((getb(g.P_SYNTAX, P_SBITS) & P_SONUMS) == 0) {
        v_ = await PERFORM_PRSA();
        g.PRSO = false;
      } else if (!g.LIT) {
        tell(S(g.TOO_DARK), "\n");
        await STOP();
      } else {
        tell("There isn't anything to ");
        tmp = get(g.P_ITBL, P_VERBN);
        if (isVerb(V.TELL)) {
          tell("talk to");
        } else if (g.P_OFLAG || g.P_MERGED) {
          printB(get(tmp, 0));
        } else {
          await WORD_PRINT(getb(tmp, 2), getb(tmp, 3));
        }
        tell("!\n");
        v_ = false;
        await STOP();
      }
    } else {
      g.P_NOT_HERE = 0;
      g.P_MULT = false;
      if (num > 1) {
        g.P_MULT = true;
      }
      tmp = false;
      loop3: for (;;) {
        if ((cnt = cnt + 1) > num) {
          if (g.P_NOT_HERE > 0) {
            tell("[The ");
            if (!(g.P_NOT_HERE == num)) {
              tell("other ");
            }
            tell("object");
            if (!(g.P_NOT_HERE == 1)) {
              tell("s");
            }
            tell(" that you mentioned ");
            if (!(g.P_NOT_HERE == 1)) {
              tell("are");
            } else {
              tell("is");
            }
            tell("n't here.]\n");
          } else if (!tmp) {
            await REFERRING();
          }
          break loop3;
        } else {
          if (ptbl) {
            obj1 = get(g.P_PRSO, cnt);
          } else {
            obj1 = get(g.P_PRSI, cnt);
          }
          g.PRSO = ptbl ? obj1 : obj;
          g.PRSI = ptbl ? obj : obj1;
          if ((num > 1) || eq(get(get(g.P_ITBL, P_NC1), 0), W.ALL, W.EVERYT)) {
            if (await DONT_ALL(obj1)) {
              continue loop3;
            } else {
              if (obj1 == IT) {
                await DPRINT(g.P_IT_OBJECT);
              } else if (obj1 == HIM) {
                await DPRINT(g.P_HIM_OBJECT);
              } else if (obj1 == HER) {
                await DPRINT(g.P_HER_OBJECT);
              } else {
                await DPRINT(obj1);
              }
              tell(": ");
            }
          }
          tmp = true;
          v_ = await PERFORM_PRSA(g.PRSO, g.PRSI);
          if (v_ == M_FATAL) {
            break loop3;
          }
        }
      }
    }
    if (v_ == M_FATAL) {
      g.P_CONT = false;
    }
    if ((await CLOCKER_VERB$()) && !(isVerb(V.TELL)) && g.P_WON) {
      v_ = await apply(getProp(g.HERE, P.ACTION), M_END);
    }
  } else {
    g.P_CONT = false;
  }
  if (g.P_WON) {
    if (await CLOCKER_VERB$()) {
      v_ = await CLOCKER();
    }
    g.P_PRSA_WORD = false;
    g.PRSA = false;
    g.PRSO = false;
    g.PRSI = false;
  }
  if (g.AWAITING_FAKE_ORPHAN && !g.P_OFLAG) {
    return await ORPHAN_VERB();
  } else {
    return false;
  }
}

async function TOO_DARK_FOR_IT$() {
  if (!g.LIT && !(await ULTIMATELY_IN$(g.P_IT_OBJECT, g.WINNER)) && !(loc(g.WINNER) == g.P_IT_OBJECT)) {
    tell(S(g.TOO_DARK), "\n");
    return true;
  } else {
    return false;
  }
}

async function DONT_ALL(obj1) {
  let l = loc(obj1);
  if (obj1 == NOT_HERE_OBJECT) {
    g.P_NOT_HERE = g.P_NOT_HERE + 1;
    return true;
  } else if (isVerb(V.TAKE) && g.PRSI && !(loc(g.PRSO) == g.PRSI)) {
    return true;
  } else if (!(await ACCESSIBLE$(obj1))) {
    return true;
  } else if (g.P_GETFLAGS == P_ALL) {
    if (g.PRSI && (g.PRSO == g.PRSI)) {
      return true;
    } else if (isVerb(V.TAKE)) {
      if (!(hasFlag(obj1, TAKEBIT)) && !(hasFlag(obj1, TRYTAKEBIT))) {
        return true;
      } else if (!(l == g.WINNER || l == g.HERE || l == g.PRSI) && !(l == loc(g.WINNER))) {
        if (hasFlag(l, SURFACEBIT) && !(hasFlag(l, TAKEBIT))) {
          return false;
        } else {
          return true;
        }
      } else if (!g.PRSI && (await ULTIMATELY_IN$(g.PRSO))) {
        return true;
      } else {
        return false;
      }
    } else if (isVerb(V.DROP, V.PUT, V.PUT_ON, V.GIVE, V.SGIVE) && !(loc(obj1) == g.WINNER)) {
      return true;
    } else if (isVerb(V.PUT, V.PUT_ON) && !(loc(g.PRSO) == g.WINNER) && (await ULTIMATELY_IN$(g.PRSO, g.PRSI))) {
      return true;
    } else {
      return false;
    }
  } else {
    return false;
  }
}

