  put(g.OOPS_TABLE, O_PTR, ptr);
  tell("[I don't know the word \"");
  await WORD_PRINT(getb(g.P_LEXV + (buf = ptr * 2), 2), getb(g.P_LEXV + buf, 3));
  tell(".\"]\n");
