async function V_LEWD() {
  let acceptable_age = false;
  if (g.NAUGHTY_LEVEL == 2) {
    tell(S(g.ALREADY_IN_MODE));
    return true;
  } else if (g.AGE > 17) {
    acceptable_age = true;
  } else {
    putb(g.P_LEXV, 0, 10);
    tell("What is your age? >");
    loop1: for (;;) {
      await read(g.P_INBUF, g.P_LEXV);
      crlf();
      if (eq(await NUMBER$(P_LEXSTART), W.NUMBER)) {
        if (g.P_NUMBER < 18) {
          g.AGE = g.P_NUMBER;
          if (g.P_NUMBER < 5) {
            tell("Precocious, aren't you! Unfortunately");
          } else {
            tell("Sorry");
          }
          tell(", you must be at least 18 to enter LEWD mode.\n");
          break loop1;
        } else if (g.P_NUMBER > 120) {
          tell("Bullpuckies. Tell the truth. >");
        } else if ((g.AGE > (-1)) && (g.AGE < 19)) {
          tell("Liar! You said before that you were ", N(g.AGE), S(g.PERIOD_CR));
          break loop1;
        } else {
          g.AGE = g.P_NUMBER;
          tell("Acceptable age. ");
          acceptable_age = true;
          break loop1;
        }
      } else {
        tell("Please tell me your age! >");
      }
    }
    putb(g.P_LEXV, 0, 60);
  }
  if (acceptable_age) {
    tell("Switching to LEWD level.\n");
    return g.NAUGHTY_LEVEL = 2;
  } else {
    return false;
  }
}

