async function V_DIAGNOSE() {
  if (!(hasFlag(CELL, TOUCHBIT))) {
    tell("You're pretty drunk");
    if (await RUNNING$(I_URGE.id)) {
      tell(", and your bladder is about to burst");
    }
  } else if (g.ION_DEATH_COUNTER > 0) {
    tell("You now have a ", S(get(g.ION_TABLE, g.ION_DEATH_COUNTER)), " headache");
  } else if (hasFlag(CATACOMBS, MUNGBIT) && (await IN_CATACOMBS())) {
    tell("You have some tiny wounds");
  } else if ((g.GONE_APE && (g.SUGAR_RUSH == GORILLA_ATE_CHOCOLATE)) || (!g.GONE_APE && (g.SUGAR_RUSH == HUMAN_ATE_CHOCOLATE))) {
    tell("You're experiencing a sugar rush");
  } else if ((g.HERE == RUINED_CASTLE_2) && hasFlag(g.HERE, MUNGBIT) && !(g.NAUGHTY_LEVEL == 0)) {
    tell("You feel ");
    if (g.NAUGHTY_LEVEL == 1) {
      tell("sexually unsatisfied");
    } else {
      tell("horny");
    }
  } else if ((g.HERE == IN_SPACE) && !(hasFlag(WHITE_SUIT, WORNBIT))) {
    tell("Brrr");
  } else {
    tell("You are in good health");
    if (g.GONE_APE) {
      tell(" (for a gorilla)");
    }
  }
  tell(S(g.PERIOD_CR));
  return true;
}

