async function YES$() {
  restart: for (;;) {
    print(">");
    await read(g.P_INBUF, g.P_LEXV);
    if (await YES_WORD(get(g.P_LEXV, 1))) {
      return true;
    } else if ((await NO_WORD(get(g.P_LEXV, 1))) || eq(get(g.P_LEXV, 1), W.N)) {
      return false;
    } else {
      tell("Please answer YES or NO. ");
      continue restart;
    }
  }
}

async function FINISH() {
  let repeating = false, cnt = 0;
  loop1: for (;;) {
    crlf();
    if (!repeating) {
      repeating = true;
      await TELL_SCORE();
    }
    tell("Would you like to start over, restore a saved position, or end this session of the game?\n(Type RESTART, RESTORE, or QUIT): >");
    putb(g.P_LEXV, 0, 10);
    await read(g.P_INBUF, g.P_LEXV);
    putb(g.P_LEXV, 0, 60);
    cnt = cnt + 1;
    if (eq(get(g.P_LEXV, 1), W.RESTAR)) {
      await restart();
      tell(S(g.FAILED));
      continue loop1;
    } else if (eq(get(g.P_LEXV, 1), W.RESTOR) && !(await restore())) {
      tell(S(g.FAILED));
      continue loop1;
    } else if (eq(get(g.P_LEXV, 1), W.QUIT, W.Q) || (cnt > 10)) {
      await quit();
    }
    continue loop1;
  }
}

