async function V_EMPTY() {
  let obj = 0, nxt = 0;
  if (!g.PRSI) {
    g.PRSI = GROUND;
  }
  if (!(hasFlag(g.PRSO, CONTBIT))) {
    tell(S(g.HUH));
    return true;
  } else if (!(hasFlag(g.PRSO, OPENBIT))) {
    tell("But");
    await TPRINT_PRSO();
    tell(" isn't open.\n");
    return true;
  } else if (!(first(g.PRSO))) {
    tell("But");
    await TPRINT_PRSO();
    tell(" is already empty!\n");
    return true;
  } else if ((g.PRSI == first(g.PRSO)) && !(next(g.PRSI))) {
    tell(S(g.THERES_NOTHING), "in");
    await TPRINT_PRSO();
    tell(" but");
    await TRPRINT(g.PRSI);
    return true;
  } else if (await IN_SPACE$()) {
    tell(S(g.YOU_CANT), "empty");
    await TPRINT_PRSO();
    tell(" without gravity!\n");
    return true;
  } else {
    obj = first(g.PRSO);
    for (;;) {
      nxt = next(obj);
      if (!(obj == PROTAGONIST)) {
        await DPRINT(obj);
        tell(": ");
        if ((g.PRSI == TRELLIS) && (obj == LEAVES)) {
          await PERFORM(V.PUT_ON, LEAVES, TRELLIS);
        } else if (hasFlag(obj, TAKEBIT)) {
          move(obj, PROTAGONIST);
          if (g.PRSI == HANDS) {
            tell("Taken.\n");
          } else if (g.PRSI == GROUND) {
            await PERFORM(V.DROP, obj);
          } else if (hasFlag(g.PRSI, SURFACEBIT)) {
            await PERFORM(V.PUT_ON, obj, g.PRSI);
          } else {
            await PERFORM(V.PUT, obj, g.PRSI);
          }
        } else {
          await YUKS();
        }
      }
      if (nxt) {
        obj = nxt;
      } else {
        return true;
      }
    }
  }
}

