async function PRE_PUT() {
  if (g.PRSO == COCK || g.PRSO == TITS || g.PRSO == CUNT) {
    return false;
  } else if (g.PRSI == GROUND) {
    if (await NOUN_USED(W.STAIN, STAIN)) {
      return false;
    } else if ((g.PRSO == CREAM) && !(eq(get(g.P_NAMW, 0), W.JAR))) {
      return false;
    }
    await PERFORM(V.DROP, g.PRSO);
    return true;
  } else if (g.PRSO == HANDS) {
    if (isVerb(V.PUT_ON, V.PUT) && hasFlag(g.PRSI, PARTBIT)) {
      return false;
    } else if (isVerb(V.PUT)) {
      await PERFORM(V.REACH_IN, g.PRSI);
      return true;
    } else {
      return await IMPOSSIBLES();
    }
  } else if (!(hasFlag(g.PRSI, PARTBIT)) && (await PLAYER_CANT_SEE())) {
    return true;
  } else if (await ULTIMATELY_IN$(g.PRSI, g.PRSO)) {
    if ((g.PRSO == BABY) && (g.PRSI == BLANKET)) {
      tell(S(g.ALREADY_IS));
      return true;
    } else {
      tell(S(g.YOU_CANT), "put");
      await TPRINT_PRSO();
      if (eq(get(g.P_ITBL, P_PREP2), PR.ON)) {
        tell(" on");
      } else {
        tell(" in");
      }
      await TPRINT_PRSI();
      tell(" when");
      await TPRINT_PRSI();
      tell(" is already ");
      if (hasFlag(g.PRSO, SURFACEBIT)) {
        tell("on");
      } else {
        tell("in");
      }
      await TPRINT_PRSO();
      tell("!\n");
      return true;
    }
  } else if (isVerb(V.PUT_ON) && (g.PRSO == SOD) && (g.PRSI == HOLE)) {
    return false;
  } else if (await UNTOUCHABLE$(g.PRSI)) {
    return await CANT_REACH(g.PRSI);
  } else if (await IDROP()) {
    return true;
  } else {
    return false;
  }
}

async function V_PUT() {
  if (!(hasFlag(g.PRSI, OPENBIT)) && !(hasFlag(g.PRSI, CONTBIT)) && !(hasFlag(g.PRSI, SURFACEBIT)) && !(hasFlag(g.PRSI, VEHBIT))) {
    tell(S(g.YOU_CANT), "put");
    await TPRINT_PRSO();
    tell(" in");
    await APRINT(g.PRSI);
    tell("!\n");
    return true;
  } else if ((g.PRSI == g.PRSO) || ((await ULTIMATELY_IN$(g.PRSO)) && !(hasFlag(g.PRSO, TAKEBIT)))) {
    tell("How can you do that?\n");
    return true;
  } else if (hasFlag(g.PRSI, DOORBIT)) {
    tell(S(g.CANT_FROM_HERE));
    return true;
  } else if (!(hasFlag(g.PRSI, OPENBIT)) && !(hasFlag(g.PRSI, SURFACEBIT))) {
    await THIS_IS_IT(g.PRSI);
    return (await DO_FIRST("open", g.PRSI));
  } else if (loc(g.PRSO) == g.PRSI) {
    tell("But");
    await TPRINT_PRSO();
    tell(" is already in");
    await TRPRINT(g.PRSI);
    return true;
  } else if (hasFlag(g.PRSI, ACTORBIT) || (g.PRSI == STALLION || g.PRSI == BABY)) {
    tell(S(g.HUH));
    return true;
  } else if (((((await WEIGHT(g.PRSI)) + (await WEIGHT(g.PRSO))) - getProp(g.PRSI, P.SIZE)) > getProp(g.PRSI, P.CAPACITY)) && !(await ULTIMATELY_IN$(g.PRSO, g.PRSI))) {
    tell("There's no room ");
    if (hasFlag(g.PRSI, SURFACEBIT)) {
      tell("on");
    } else {
      tell("in");
    }
    await TPRINT_PRSI();
    tell(" for");
    await TRPRINT(g.PRSO);
    return true;
  } else if (!(await ULTIMATELY_IN$(g.PRSO)) && eq(await ITAKE(), M_FATAL, false)) {
    return true;
  } else if (((g.PRSO == TORCH) || (await ULTIMATELY_IN$(TORCH, g.PRSO))) && hasFlag(TORCH, ONBIT) && (g.PRSI == BASKET || g.PRSI == SACK)) {
    return (await DO_FIRST("extinguish", TORCH));
  } else if (loc(g.PRSI) == ODD_MACHINE) {
    tell(S(g.ONLY_ONE_THING_IN_COMPARTMENT));
    return true;
  } else {
    move(g.PRSO, g.PRSI);
    setFlag(g.PRSO, TOUCHBIT);
    tell("Done.\n");
    return true;
  }
}

