async function CCOUNT(obj) {
  let cnt = 0, x = 0;
  if (x = first(obj)) {
    loop1: for (;;) {
      if (!(hasFlag(x, WORNBIT))) {
        cnt = cnt + 1;
      }
      if (!(x = next(x))) {
        break loop1;
      }
    }
  }
  return cnt;
}

async function WEIGHT(obj) {
  let cont = 0, wt = 0;
  if (cont = first(obj)) {
    loop1: for (;;) {
      wt = wt + (await WEIGHT(cont));
      if (!(cont = next(cont))) {
        break loop1;
      }
    }
  }
  return wt + getProp(obj, P.SIZE);
}

async function DESCRIBE_ROOM(verb_is_look = false) {
  let first_visit = false, num = 0;
  if (!g.LIT) {
    tell(S(g.TOO_DARK));
    if ((g.HERE == CLOSET) && !(hasFlag(NOSE, MUNGBIT))) {
      tell(" There's a distinctive odor here, though.");
    }
    crlf();
    return false;
  }
  if (!(hasFlag(g.HERE, TOUCHBIT))) {
    if (!(g.HERE == CANAL || g.HERE == CATACOMBS || g.HERE == LONG_CORRIDOR)) {
      setFlag(g.HERE, TOUCHBIT);
    }
    first_visit = true;
  }
  await DPRINT(g.HERE);
  num = await CANAL_LOC();
  if (num == 10) {
    tell(", near the ");
    if (g.NEARER_DOCK == MY_KIND_OF_DOCK) {
      tell("ea");
    } else {
      tell("we");
    }
    tell("st bank");
  }
  if (hasFlag(loc(PROTAGONIST), VEHBIT) && !g.DONT_PRINT_VEHICLE) {
    tell(", ");
    if (hasFlag(loc(PROTAGONIST), INBIT)) {
      tell("i");
    } else {
      tell("o");
    }
    tell("n");
    await TPRINT(loc(PROTAGONIST));
  }
  crlf();
  if (verb_is_look || (g.VERBOSITY == 2) || (first_visit && (g.VERBOSITY == 1))) {
    tell("   ");
    if (!(await apply(getProp(g.HERE, P.ACTION), M_LOOK))) {
      tell(S(getProp(g.HERE, P.LDESC)));
    }
    crlf();
  }
  return true;
}

async function DESCRIBE_OBJECTS() {
  let o = 0, str = 0, _1st$ = true, av = loc(g.WINNER);
  o = first(g.HERE);
  if (!o) {
    return false;
  }
  loop1: for (;;) {
    if (!o) {
      break loop1;
    } else if ((await DESCRIBABLE$(o)) && !(hasFlag(o, TOUCHBIT)) && (str = getProp(o, P.FDESC))) {
      tell("   ", S(str));
      if (hasFlag(o, CONTBIT)) {
        await DESCRIBE_CONTENTS(o, true, D_ALL$ + D_PARA$);
      }
      crlf();
    }
    o = next(o);
  }
  o = first(g.HERE);
  _1st$ = true;
  loop2: for (;;) {
    if (!o) {
      break loop2;
    } else if (!(await DESCRIBABLE$(o)) || (getProp(o, P.FDESC) && !(hasFlag(o, TOUCHBIT)))) {
    } else if ((str = getProp(o, P.DESCFCN)) && (str = await apply(str, M_OBJDESC))) {
      if (hasFlag(o, CONTBIT) && (str != M_FATAL)) {
        await DESCRIBE_CONTENTS(o, true, D_ALL$ + D_PARA$);
      }
      crlf();
    } else if (str = getProp(o, P.LDESC)) {
      tell("   ", S(str));
      if (hasFlag(o, CONTBIT)) {
        await DESCRIBE_CONTENTS(o, true, D_ALL$ + D_PARA$);
      }
      crlf();
    }
    o = next(o);
  }
  await DESCRIBE_CONTENTS(g.HERE, false, 0);
  if (av && !(g.HERE == av)) {
    return await DESCRIBE_CONTENTS(av, false, 0);
  } else {
    return false;
  }
}

async function DESCRIBE_CONTENTS(obj, level = (-1), all$ = D_ALL$) {
  let f = false, n_ = 0, _1st$ = true, it$ = false, start$ = false, two$ = false, para$ = false;
  if (level == 2) {
    level = true;
    para$ = true;
    start$ = true;
  } else if (btst(all$, D_PARA$)) {
    para$ = true;
  }
  n_ = first(obj);
  if (start$ || (loc(obj) == ROOMS) || hasFlag(obj, ACTORBIT) || (hasFlag(obj, CONTBIT) && (hasFlag(obj, OPENBIT) || hasFlag(obj, TRANSBIT)) && hasFlag(obj, SEARCHBIT) && n_)) {
    loop1: for (;;) {
      if (!n_ || ((await DESCRIBABLE$(n_)) && (btst(all$, D_ALL$) || (await SIMPLE_DESC$(n_))))) {
        if (f) {
          if (_1st$) {
            _1st$ = false;
            if (level == false || level == true) {
              if (!start$) {
                if (!para$) {
                  if (!(obj == PROTAGONIST)) {
                    tell("   ");
                  }
                  para$ = true;
                } else if (level == true) {
                  tell(" ");
                }
                if (obj == g.HERE) {
                  tell(S(g.YOU_SEE));
                } else if (obj == PROTAGONIST) {
                  tell("You have");
                } else if (hasFlag(obj, SURFACEBIT)) {
                  tell("Sitting on");
                  await TPRINT(obj);
                  tell(" is");
                } else {
                  tell(S(g.IT_SEEMS_THAT));
                  await TPRINT(obj);
                  if (hasFlag(obj, ACTORBIT)) {
                    tell(" has");
                  } else {
                    tell(" contains");
                  }
                }
              }
            } else if (!(level == (-1))) {
              tell(S(level));
            }
          } else {
            if (n_) {
              tell(",");
            } else {
              tell(" and");
            }
          }
          await APRINT(f);
          if (hasFlag(f, WORNBIT)) {
            if (f == LIP_BALM) {
              tell(" (smeared all over your lips)");
            } else if (f == COTTON_BALLS) {
              tell(" (stuffed in ", D(EARS), ")");
            } else if (f == CLOTHES_PIN) {
              tell(" (pinned to ", D(NOSE), ")");
            } else {
              tell(" (being worn)");
            }
          } else if (hasFlag(f, ONBIT)) {
            tell(" (providing light)");
          } else if (f == COMIC_BOOK) {
            tell(" (stuck in your back pocket)");
          }
          if (!it$ && !two$) {
            it$ = f;
          } else {
            two$ = true;
            it$ = false;
          }
        }
        f = n_;
      }
      if (n_) {
        n_ = next(n_);
      }
      if (!f && !n_) {
        if (it$ && !two$) {
          await THIS_IS_IT(it$);
        }
        if (_1st$ && start$) {
          tell(" nothing");
          return false;
        }
        if (!_1st$ && (level == false || level == true)) {
          if (obj == g.HERE) {
            tell(" here");
          }
          tell(".");
        }
        break loop1;
      }
    }
    f = first(obj);
    loop2: for (;;) {
      if (!f) {
        break loop2;
      } else if (hasFlag(f, CONTBIT) && (await DESCRIBABLE$(f, true)) && (btst(all$, D_ALL$) || (await SIMPLE_DESC$(f)))) {
        if (await DESCRIBE_CONTENTS(f, true, para$ ? (D_ALL$ + D_PARA$) : D_ALL$)) {
          _1st$ = false;
          para$ = true;
        }
      }
      f = next(f);
    }
    if (!_1st$ && (level == false || level == true) && (obj == g.HERE || obj == loc(g.WINNER))) {
      crlf();
    }
    return !_1st$;
  } else {
    return false;
  }
}

