async function FIND_IN(where, flag_in_question, string = false) {
  let obj = 0, recursive_obj = 0;
  obj = first(where);
  if (!obj) {
    return false;
  }
  for (;;) {
    if (hasFlag(obj, flag_in_question) && !(hasFlag(obj, INVISIBLE))) {
      if (string) {
        tell("[", S(string));
        await TPRINT(obj);
        tell("]\n");
      }
      return obj;
    } else if (recursive_obj = await FIND_IN(obj, flag_in_question)) {
      return recursive_obj;
    } else if (!(obj = next(obj))) {
      return false;
    }
  }
}

