async function GROUND_F() {
  if (g.HERE == IN_SPACE) {
    await CANT_SEE(GROUND);
    return true;
  } else if (hasFlag(g.HERE, INDOORSBIT) || eq(loc(PROTAGONIST), BARGE)) {
    putProp(GROUND, P.SDESC, "floor");
  } else {
    putProp(GROUND, P.SDESC, "ground");
  }
  if (isVerb(V.EXAMINE)) {
    if (g.HERE == SPAWNING_GROUND) {
      tell(S(g.OOZY_WITH_SLIME), "\n");
      return true;
    } else if ((await GLOBAL_IN$(HOLE, g.HERE)) && !(await HOLE_INVISIBLE())) {
      tell("You notice");
      await ARPRINT(HOLE);
      return true;
    } else if (g.HERE == CELL) {
      tell("Soft. Cushiony.\n");
      return true;
    } else if (g.HERE == OTHER_CELL) {
      tell("Rock-hard.\n");
      return true;
    } else if ((g.HERE == HOLD) && (g.SIDEKICK_EXPLODED == 1)) {
      await SPLATTERED_DESC();
      return crlf();
    } else if (await IN_CATACOMBS()) {
      tell(S(g.CATACOMBS_WATER_DESC), "\n");
      return true;
    } else {
      return false;
    }
  } else if (isVerb(V.TOUCH) && (g.HERE == CELL || g.HERE == OTHER_CELL)) {
    await PERFORM(V.EXAMINE, GROUND);
    return true;
  } else if (isVerb(V.CLIMB_UP, V.CLIMB_ON, V.CLIMB, V.BOARD)) {
    return await WASTES();
  } else if (isVerb(V.LOOK_UNDER)) {
    return await IMPOSSIBLES();
  } else if (isVerb(V.LEAVE)) {
    return await DO_WALK(P.UP);
  } else if (isVerb(V.LEAP, V.STAND_ON) && (g.HERE == ROOF)) {
    await PERFORM(V.LEAP, ROOMS);
    return true;
  } else {
    return false;
  }
}

