async function HOLE_F() {
  let old_here = 0;
  if ((!(await CIRCLE_ISNT_BLACK()) && (g.PRSO == HOLE) && eq(get(g.P_ADJW, 0), A.WHITE)) || (!(await CIRCLE_ISNT_BLACK()) && (g.PRSI == HOLE) && eq(get(g.P_ADJW, 1), A.WHITE)) || ((await CIRCLE_ISNT_BLACK()) && (g.PRSO == HOLE) && eq(get(g.P_ADJW, 0), A.BLACK)) || ((await CIRCLE_ISNT_BLACK()) && (g.PRSI == HOLE) && eq(get(g.P_ADJW, 1), A.BLACK))) {
    return await CANT_SEE(HOLE);
  } else if (await HOLE_INVISIBLE()) {
    return await CANT_SEE(HOLE);
  } else if ((g.HERE == CELL) && (await NOUN_USED(W.HOLE, HOLE)) && isVerb(V.BOARD, V.ENTER, V.WALK_TO, V.LOOK_INSIDE)) {
    return await DO_WALK(P.UP);
  } else if (eq(loc(PROTAGONIST), CAGE, FIRST_SLAB, SECOND_SLAB) && (await TOUCHING$(HOLE))) {
    await CANT_REACH(HOLE);
    return true;
  } else if (isVerb(V.STAND_ON, V.ENTER, V.BOARD)) {
    if (await CIRCLE_ISNT_BLACK()) {
      tell(S(g.NOTHING_HAPPENS));
      return true;
    } else if (!(loc(PROTAGONIST) == g.HERE)) {
      await NOT_GOING_ANYWHERE();
      return true;
    }
    await FALL_THROUGH_HOLE();
    g.LONG_CORRIDOR_LOC = 1;
    g.MAD_SCIENTIST_COUNTER = 0;
    g.IMPATIENCE_COUNTER = 0;
    await DEQUEUE(I_MAD_SCIENTIST.id);
    old_here = g.HERE;
    if (g.HERE == LONG_CORRIDOR) {
      tell("Geronimo!\n   Yow! You appear in midair, high above a canal-studded desertscape. The ground is approaching uncomfortably fast.\n   Caw! Caw! A pterodactyl snatches you");
      await AND_SIDEKICK();
      tell(" in midair and deposits you safely in", S(g.ELLIPSIS));
      if (hasFlag(MY_KIND_OF_DOCK, TOUCHBIT) && prob(60)) {
        await GOTO(MY_KIND_OF_DOCK);
      } else if (hasFlag(OASIS, TOUCHBIT) && prob(40)) {
        await GOTO(OASIS);
      } else {
        await GOTO(RUINED_CASTLE_2);
      }
    } else {
      await GOTO(getProp(g.HERE, P.HOLE_DESTINATION));
    }
    if ((old_here == WELL_BOTTOM) && (loc(SIDEKICK) == WELL_BOTTOM)) {
      g.HOLE_MOVE = true;
      await SIDEKICK_FOLLOWS_YOU();
      g.HOLE_MOVE = false;
    }
    return true;
  } else if (isVerb(V.LOOK_UNDER, V.TAKE)) {
    tell("It's not liftable.\n");
    return true;
  } else if (isVerb(V.POUR, V.RUB, V.PUT_ON) && (await NOUN_USED(W.STAIN, STAIN)) && (g.PRSO == STAIN)) {
    return await APPLY_STAIN(HOLE);
  } else if (isVerb(V.PUT, V.PUT_ON, V.PUT_THROUGH) && (g.PRSI == HOLE)) {
    if (await CIRCLE_ISNT_BLACK()) {
      return await WASTES();
    } else if (g.PRSO == SOD) {
      return false;
    } else {
      if (g.HERE == LONG_CORRIDOR) {
        remove(g.PRSO);
      } else {
        if ((g.PRSO == TORCH) && (g.HERE == WELL_BOTTOM)) {
          await TORCH_OFF();
        }
        move(g.PRSO, getProp(g.HERE, P.HOLE_DESTINATION));
      }
      return await NON_DIMENSIONAL_JOURNEY();
    }
  } else if (await CIRCLE_ISNT_BLACK()) {
    return false;
  } else if (isVerb(V.REACH_IN, V.TOUCH)) {
    tell(S(g.HAND_DWINDLES));
    return true;
  } else if (isVerb(V.EXAMINE, V.LOOK_INSIDE)) {
    tell(S(g.STARING_INTO_VOID));
    return true;
  } else if (isVerb(V.MEASURE)) {
    await PERFORM_PRSA(FLEXIBLE_HOLE);
    return true;
  } else {
    return false;
  }
}

