async function I_URGE() {
  await QUEUE(I_URGE.id, -1);
  g.URGE_COUNTER = g.URGE_COUNTER + 1;
  tell("   ");
  if (g.URGE_COUNTER == 1) {
    tell("You feel an urge.\n");
    return true;
  } else if (g.URGE_COUNTER == 2) {
    tell("You trace the urge to the region of your bladder.\n");
    return true;
  } else if (g.URGE_COUNTER == 3) {
    tell("Though operating at far below normal speed, your mind begins to conclude that it would be best at this point to ");
    if (g.HERE == MENS_ROOM || g.HERE == LADIES_ROOM) {
      tell("use the");
    } else {
      tell("find a");
    }
    tell(" bathroom.\n");
    return true;
  } else if (g.URGE_COUNTER == 4) {
    tell("Even if you don't care about your clothes, imagine the embarrassment!\n");
    return true;
  } else {
    tell(S(g.YOU_CANT), "wait another second. ");
    if (g.HERE == MENS_ROOM || g.HERE == LADIES_ROOM) {
      await QUEUE(I_KIDNAPPING.id, 3);
      await DEQUEUE(I_URGE.id);
      move(PROTAGONIST, g.HERE);
      tell("Fortunately, you've stumbled upon a bathroom. A moment later, you are feeling much better, although your thigh muscles are still quivering a tad.");
      return await NOTICE_PIZZA_ODOR();
    } else {
      tell("Without going into embarrassing detail, you've made a mess. A moment later, before even half the people in Joe's have begun tittering, a flash of green light precedes the arrival of two VERY odd patrons. They rotate their bellies to get a better look at you. As their mouth stalks open you find that, despite an evolution that occurred dozens of astronomical units from Upper Sandusky, these fellows speak in perfect midwestern English.\n   \"This one?\"\n   \"A pitiful specimen ... can't even control simple bodily functions ... the tests would be worthless...\"\n   \"Agreed. Must've been a screw-up somewhere. Let's take this one instead.\"\n   They grab a blonde woman, whose scream is cut short by another green flash. Three weeks later, when the Earth is invaded and everyone is enslaved by ", D(LGOP), ", you wonder if there was a connection.\n");
      return await FINISH();
    }
  }
}

