async function BABY_F(oarg = false) {
  if (oarg) {
    if (hasFlag(BABY, TOUCHBIT)) {
      return false;
    } else {
      if (oarg == M_OBJDESC$) {
        return true;
      }
      tell("   A little baby robot is shivering in the corner. It stops crying long enough to open a tiny metal eyelid and look at you. \"");
      if (g.MALE) {
        tell("Momm");
      } else {
        tell("Dadd");
      }
      tell("y?\" it says, in a quavering, high-pitched, metallic voice.");
      return true;
    }
  } else if (isVerb(V.TELL)) {
    if (loc(BLANKET) == BABY) {
      g.WINNER = PROTAGONIST;
      await PERFORM(V.KISS, BABY);
    } else {
      tell("\"Goo goo ga ga buzz whirr click.\"\n");
    }
    return await STOP();
  } else if ((isVerb(V.PUT) && (g.PRSI == BLANKET)) || (isVerb(V.PUT_ON, V.WRAP) && (g.PRSO == BLANKET)) || (isVerb(V.PUT) && (g.PRSI == BASKET) && (loc(BLANKET) == BASKET))) {
    if (hasFlag(BLANKET, UNTEEDBIT)) {
      return false;
    } else if (loc(BLANKET) == BABY) {
      tell(S(g.SENILITY_STRIKES));
      return true;
    }
    setFlag(BABY, TOUCHBIT);
    setFlag(BLANKET, NDESCBIT);
    move(BLANKET, BABY);
    if (g.PRSI == BASKET) {
      move(BABY, BASKET);
    }
    putProp(BABY, P.SDESC, "baby robot wrapped in a blanket");
    await DEQUEUE(I_CRY.id);
    tell("The baby stops crying and, in the comfy warmth of the blanket, slips into a calm sleep. A peaceful smile creeps over its face.\n");
    return true;
  } else if ((isVerb(V.PUT) && (g.PRSI == SHEET)) || (isVerb(V.PUT_ON, V.WRAP) && (g.PRSO == SHEET))) {
    if ((loc(BLANKET) == BABY) || hasFlag(SHEET, MUNGBIT) || hasFlag(SHEET, PLURALBIT)) {
      return await WASTES();
    } else {
      tell("The sheet provides little warmth.\n");
      return true;
    }
  } else if (isVerb(V.PUT) && (g.PRSI == BASKET) && (loc(BASKET) == FRONT_STOOP) && !(first(BASKET))) {
    if (loc(BLANKET) == BABY) {
      move(BABY, BASKET);
      return (await ABANDON_BABY("in the basket"));
    } else {
      return await CRYING_ALERTS_MATRON();
    }
  } else if (isVerb(V.REMOVE) && (loc(BLANKET) == BABY)) {
    move(BLANKET, PROTAGONIST);
    clearFlag(BLANKET, NDESCBIT);
    putProp(BABY, P.SDESC, "robot infant");
    await QUEUE(I_CRY.id, -1);
    tell("The baby robo", S(g.TWICE_AS_LOUD));
    if (await ULTIMATELY_IN$(BABY, FRONT_STOOP)) {
      tell("   ");
      await CRYING_ALERTS_MATRON();
    }
    return true;
  } else if (isVerb(V.KISS)) {
    if (loc(BLANKET) == BABY) {
      await PERFORM(V.ALARM, BABY);
      return true;
    } else {
      tell("The ");
      await DPRINT(BABY);
      tell(" reacts as a human baby would react if kissed by a giant walking metal machine. In other words, i", S(g.TWICE_AS_LOUD));
      return true;
    }
  } else if (isVerb(V.LISTEN) && !(loc(BLANKET) == BABY)) {
    tell("\"Waaaa!\"\n");
    return true;
  } else if (isVerb(V.SHAKE)) {
    if (loc(BLANKET) == BABY) {
      tell("The baby's asleep!\n");
      return true;
    } else {
      tell("This upsets the ");
      await DPRINT(BABY);
      tell("'s equilibrium mechanism. I", S(g.TWICE_AS_LOUD));
      return true;
    }
  } else if (isVerb(V.ALARM) && (loc(BLANKET) == BABY)) {
    tell("The baby whimpers briefly, but the warm coziness of the blanket soon lulls it back to sleep.\n");
    return true;
  } else if (await TAKE_BABY_FROM_STOOP(BABY)) {
    return true;
  } else if (isVerb(V.SUCKLE)) {
    if (g.MALE) {
      tell("You're a male, remember? You obviously have a poor mammary.\n");
      return true;
    } else {
      tell("How touching that the baby robot has stirred your maternal instinct. Unfortunately, your mammaries won't produce #3 machine oil.\n");
      return true;
    }
  } else if (isVerb(V.PUT, V.PUT_NEAR) && (g.PRSI == ORPHANAGE_DOOR)) {
    await PERFORM(V.PUT_ON, BABY, FRONT_STOOP);
    return true;
  } else if (isVerb(V.EXAMINE)) {
    tell("The ");
    await DPRINT(BABY);
    tell(" is ");
    if (loc(BLANKET) == BABY) {
      tell("sleep");
    } else {
      tell("cry");
    }
    tell("ing.\n");
    return true;
  } else if (isVerb(V.OPEN, V.CLOSE)) {
    tell(S(g.HUH));
    return true;
  } else {
    return false;
  }
}

async function CRYING_ALERTS_MATRON() {
  tell("The baby's crying alerts someone within the igloo. ");
  return (await SHOO("abandon"));
}

async function SHOO(string) {
  await DEQUEUE(I_ORPHANAGE.id);
  tell(S(g.MATRON_DESC), "appears. \"Caught you, you baby-", S(string), "ing gypsy!\" she cries, in a voice that, in a more mountainous region, could probably initiate an avalanche. \"Begone!\" She ");
  if (await ULTIMATELY_IN$(BABY, FRONT_STOOP)) {
    tell("thrusts the babe into your arms and ");
  }
  if (loc(BASKET) == FRONT_STOOP) {
    move(BASKET, PROTAGONIST);
  }
  if (await ULTIMATELY_IN$(BABY, FRONT_STOOP)) {
    move(BABY, PROTAGONIST);
  }
  tell("drives you away with blows that would fell an elephant.\n\n");
  if (g.HERE == ORPHANAGE_FOYER) {
    return await GOTO(SOUTH_POLE);
  } else {
    return await GOTO(GYPSY_CAMP);
  }
}

async function SOUTH_POLE_F(rarg) {
  if ((rarg == M_ENTER) && g.COTTON_BALLS_SEEN && hasFlag(COTTON_BALLS, TRYTAKEBIT)) {
    move(COTTON_BALLS, g.HERE);
    return setFlag(COTTON_BALLS, NDESCBIT);
  } else {
    return false;
  }
}

async function ORPHANAGE_DOOR_F() {
  if (isVerb(V.KNOCK) && (g.HERE == SOUTH_POLE)) {
    if (await VISIBLE$(BABY)) {
      return (await SHOO("abandon"));
    } else {
      return (await SHOO("steal"));
    }
  } else {
    return false;
  }
}

async function FRONT_STOOP_F() {
  if (isVerb(V.PUT, V.PUT_ON, V.PUT_NEAR)) {
    if ((g.PRSO == BABY) && !(loc(BABY) == BASKET)) {
      if (loc(BLANKET) == BABY) {
        await COLD_CAUSES_CRYING();
      }
      move(g.PRSO, FRONT_STOOP);
      return await CRYING_ALERTS_MATRON();
    } else if ((g.PRSO == BASKET || g.PRSO == BABY) && (loc(BABY) == BASKET)) {
      if (!(loc(BLANKET) == BABY)) {
        return await CRYING_ALERTS_MATRON();
      } else {
        move(BASKET, FRONT_STOOP);
        return (await ABANDON_BABY("on the stoop"));
      }
    } else {
      return false;
    }
  } else if (isVerb(V.BOARD, V.ENTER, V.STAND_ON)) {
    return await WASTES();
  } else if (isVerb(V.PUT) && (g.PRSO == BABY)) {
    await COLD_CAUSES_CRYING();
    return await CRYING_ALERTS_MATRON();
  } else {
    return false;
  }
}

async function COLD_CAUSES_CRYING() {
  tell("As you place the baby on the cold doorstep, i", S(g.TWICE_AS_LOUD), "   ");
  return true;
}

async function ABANDON_BABY(string) {
  await QUEUE(I_ORPHANAGE.id, 5);
  move(PROTAGONIST, g.HERE);
  tell("You place the baby gently ", S(string), " and sneak behind a nearby snowdrift.\n");
  return true;
}

async function I_ORPHANAGE() {
  remove(BABY);
  remove(BASKET);
  clearFlag(ORPHANAGE_DOOR, LOCKEDBIT);
  if (g.HERE == SOUTH_POLE) {
    g.FOLLOW_FLAG = 15;
    await QUEUE(I_FOLLOW.id, 2);
    tell("   ", S(g.MATRON_DESC), "opens the ", D(ORPHANAGE_DOOR), ". She coos over the baby for a moment then carries it inside, closing the door behind her.\n");
    return true;
  } else {
    return false;
  }
}

async function ORPHANAGE_FOYER_F(rarg) {
  if (rarg == M_ENTER) {
    if (hasFlag(COTTON_BALLS, TRYTAKEBIT)) {
      move(COTTON_BALLS, g.HERE);
      clearFlag(COTTON_BALLS, NDESCBIT);
    }
    if (!(await QUEUED$(I_ORPHANAGE_BOOT.id))) {
      return await QUEUE(I_ORPHANAGE_BOOT.id, 5);
    } else {
      return false;
    }
  } else if (rarg == M_LOOK) {
    tell("The igloo's front hall has rooms to the northeast and northwest. A barred window is next to the ");
    await OPEN_CLOSED(ORPHANAGE_DOOR);
    tell(" door to the south.");
    return true;
  } else {
    return false;
  }
}

async function IGLOO_ENTER_F() {
  tell("Nursery\n");
  await I_ORPHANAGE_BOOT();
  await DEQUEUE(I_ORPHANAGE_BOOT.id);
  return false;
}

async function I_ORPHANAGE_BOOT() {
  if (g.HERE == ORPHANAGE_FOYER) {
    tell("   ");
    (await SHOO("steal"));
    clearFlag(ORPHANAGE_DOOR, OPENBIT);
    return setFlag(ORPHANAGE_DOOR, LOCKEDBIT);
  } else if ((g.HERE == SOUTH_POLE) && hasFlag(ORPHANAGE_DOOR, OPENBIT)) {
    tell("   The ", D(ORPHANAGE_DOOR), " slams shut.\n");
    clearFlag(ORPHANAGE_DOOR, OPENBIT);
    return setFlag(ORPHANAGE_DOOR, LOCKEDBIT);
  } else {
    clearFlag(ORPHANAGE_DOOR, OPENBIT);
    setFlag(ORPHANAGE_DOOR, LOCKEDBIT);
    return false;
  }
}

async function COTTON_BALLS_F() {
  if ((g.HERE == SOUTH_POLE) && hasFlag(COTTON_BALLS, TRYTAKEBIT) && (await TOUCHING$(COTTON_BALLS))) {
    return await CANT_REACH(COTTON_BALLS);
  } else if (isVerb(V.TAKE) && hasFlag(COTTON_BALLS, TRYTAKEBIT)) {
    await INCREMENT_SCORE(16, 29, true);
    clearFlag(COTTON_BALLS, TRYTAKEBIT);
    return false;
  } else if (hasFlag(COTTON_BALLS, UNTEEDBIT)) {
    if (isVerb(V.EXAMINE)) {
      tell("Let's just say that some poor male raccoon is speaking in a particularly high-pitched voice.\n");
      return true;
    } else {
      return false;
    }
  } else if (isVerb(V.PUT, V.PUT_ON) && (g.PRSI == EARS)) {
    if (g.GONE_APE) {
      tell(S(g.DEXTERITY));
      return true;
    } else {
      setFlag(COTTON_BALLS, WORNBIT);
      setFlag(EARS, MUNGBIT);
      move(COTTON_BALLS, PROTAGONIST);
      tell(S(g.MUFFLED), " have ");
      await DPRINT(COTTON_BALLS);
      tell(" stuffed in ", D(EARS), S(g.PERIOD_CR));
      return true;
    }
  } else if (isVerb(V.REMOVE, V.DISEMBARK) && hasFlag(COTTON_BALLS, WORNBIT)) {
    if (g.GONE_APE) {
      await PERFORM(V.TAKE, COTTON_BALLS);
      return true;
    }
    await OPEN_EYES_AND_REMOVE_HANDS();
    clearFlag(COTTON_BALLS, WORNBIT);
    return await SENSE_AGAIN(EARS);
  } else if (isVerb(V.PUT) && (g.PRSI == NOSE)) {
    tell("The ", D(COTTON_BALLS), " is too itchy.\n");
    return true;
  } else {
    return false;
  }
}

async function IGLOO_F() {
  if (isVerb(V.ENTER, V.WALK_TO, V.BOARD)) {
    if (g.HERE == ORPHANAGE_FOYER) {
      tell(S(g.LOOK_AROUND));
      return true;
    } else if (g.HERE == SOUTH_POLE) {
      return await DO_WALK(P.IN);
    } else {
      return false;
    }
  } else if (isVerb(V.LEAVE, V.EXIT, V.DISEMBARK)) {
    if (g.HERE == SOUTH_POLE) {
      tell(S(g.LOOK_AROUND));
      return true;
    } else {
      return await DO_WALK(P.OUT);
    }
  } else if (isVerb(V.LOOK_INSIDE)) {
    if (g.HERE == SOUTH_POLE) {
      await PERFORM_PRSA(WINDOW);
      return true;
    } else {
      return await V_LOOK();
    }
  } else if (isVerb(V.SEARCH)) {
    tell(S(g.NOTHING_NEW));
    return true;
  } else {
    return false;
  }
}

async function VENUS_F() {
  if (isVerb(V.EXAMINE)) {
    return await V_LOOK();
  } else if (isVerb(V.LEAVE, V.DISEMBARK, V.EXIT)) {
    tell("How?\n");
    return true;
  } else {
    return false;
  }
}

async function JUNGLE_F(rarg) {
  if ((rarg == M_ENTER) && (loc(FLYTRAP) == g.HERE)) {
    return await QUEUE(I_FLYTRAP.id, -1);
  } else if (rarg == M_LOOK) {
    tell("You are surrounded by hot, steamy, primitive rain forest. Judging by the overpowering heat, the excessive humidity, and ");
    if (loc(FLYTRAP) == g.HERE) {
      tell("especially by the gigantic ", D(FLYTRAP), " sidling your way, ");
    } else {
      tell("the odd flora, ");
    }
    tell("you must be in the death-clogged jungles of Venus.\n   A path runs east-west through the jungle");
    if (loc(FLYTRAP) == g.HERE) {
      tell(", but don't even think about going west unless you love wading into four tons of ");
      if (!g.MALE) {
        tell("wo");
      }
      tell("man-eating lettuce");
    }
    tell(".");
    return true;
  } else {
    return false;
  }
}

async function PASS_FLYTRAP_F() {
  if (loc(FLYTRAP) == g.HERE) {
    tell("Despite being warned, you walk right into the orifice of the ", D(FLYTRAP), ". ");
    return await FLYTRAP_DEATH();
  } else if (g.HERE == JUNGLE) {
    return SPAWNING_GROUND;
  } else {
    return JUNGLE;
  }
}

async function FLYTRAP_DEATH() {
  tell("A little known fact about ", D(FLYTRAP), "s: they secrete an enzyme which stimulates the pleasure centers of their victim. Hence, you experience ");
  if (g.NAUGHTY_LEVEL == 0) {
    tell("a feeling similar to eating a really good hot fudge sundae");
  } else {
    tell("multiple orgasms");
  }
  return (await JIGS_UP(" as your flesh is quietly dissolved away. What a way to go."));
}

async function FLYTRAP_F() {
  if (isVerb(V.EXAMINE)) {
    tell("It looks just like the Terrestrial variety -- except that ", D(FLYTRAP), "s on Earth", S(g.EVOLVED), "n ounce, and Venusian ", D(FLYTRAP), "s", S(g.EVOLVED), " ton. Oh, one other thing. Terrestrial ", D(FLYTRAP), "s don't usually stalk their prey.\n");
    return true;
  } else if (isVerb(V.FOLLOW)) {
    if (g.FOLLOW_FLAG == 9) {
      return await DO_WALK(P.WEST);
    } else if (g.FOLLOW_FLAG == 10) {
      await PERFORM(V.DISEMBARK, TREE_HOLE);
      return true;
    } else if (g.FOLLOW_FLAG == 11) {
      await PERFORM(V.ENTER, TREE_HOLE);
      return true;
    } else {
      return false;
    }
  } else if (await TOUCHING$(FLYTRAP)) {
    tell("You don't want to get that close to the flytrap -- and it has nothing to do with its breath.\n");
    return true;
  } else {
    return false;
  }
}

async function I_FLYTRAP() {
  g.FLYTRAP_COUNTER = g.FLYTRAP_COUNTER + 1;
  tell("   ");
  if (!(loc(FLYTRAP) == g.HERE)) {
    g.FLYTRAP_COUNTER = 0;
    if (g.HERE == CLEARING) {
      if (g.LEAVES_PLACED && !g.TOO_LATE) {
        await TRAP_FLYTRAP();
        tell("You hear a crash from the west");
      } else {
        move(FLYTRAP, JUNGLE);
        g.TOO_LATE = false;
        await DEQUEUE(I_FLYTRAP.id);
        g.FOLLOW_FLAG = 9;
        await QUEUE(I_FOLLOW.id, 2);
        tell("Holy tropism! The ", D(FLYTRAP), " loses interest in you and crawls away");
      }
      tell(S(g.PERIOD_CR));
      return true;
    } else {
      move(FLYTRAP, g.HERE);
      if (!g.LEAVES_PLACED) {
        g.TOO_LATE = true;
      }
      tell("As");
      await TPRINT(FLYTRAP);
      tell(" scurries along, you dash to the eastern side of the hole in order to be as far from it as possible.\n");
      return true;
    }
  } else if (loc(PROTAGONIST) == TREE_HOLE) {
    move(FLYTRAP, JUNGLE);
    g.FOLLOW_FLAG = 10;
    await QUEUE(I_FOLLOW.id, 2);
    g.TOO_LATE = false;
    g.FLYTRAP_COUNTER = 0;
    await DEQUEUE(I_FLYTRAP.id);
    tell("The ", D(FLYTRAP), " peers down, decides that it's not worth getting trapped for such a measly scrap of meat, and shuffles away.\n");
    return true;
  } else if ((g.FLYTRAP_COUNTER == 1) && hasFlag(FLYTRAP, TOUCHBIT) && (g.HERE == JUNGLE)) {
    tell("Flies must be in short supply, because the ", D(FLYTRAP), " nearby expectantly rustles a few stalks and begins creeping in your direction.\n");
    return true;
  } else if (g.FLYTRAP_COUNTER < 4) {
    setFlag(FLYTRAP, TOUCHBIT);
    tell("The ", D(FLYTRAP), " sidles ");
    if ((g.HERE == FORK_OF_SORTS) && (!g.LEAVES_PLACED || g.TOO_LATE)) {
      tell("around the hole toward you.\n");
      return true;
    } else {
      tell("closer.\n");
      return true;
    }
  } else if ((g.HERE == FORK_OF_SORTS) && g.LEAVES_PLACED && !g.TOO_LATE) {
    await TRAP_FLYTRAP();
    tell("Never before has splintering wood sounded so sweet or tossed salad looked so lovely. The amazing flying flytrap tumbles into your flytrap trap, covered with leaves and bits of shattered trellis, giving the plant the amusing appearance of a tar-and-feather victim.\n");
    return true;
  } else {
    return await FLYTRAP_DEATH();
  }
}

async function TRAP_FLYTRAP() {
  setFlag(FLYTRAP, MUNGBIT);
  await INCREMENT_SCORE(2, 15);
  move(FLYTRAP, TREE_HOLE);
  g.FOLLOW_FLAG = 11;
  await QUEUE(I_FOLLOW.id, 2);
  await ROB(TRELLIS, TREE_HOLE);
  remove(TRELLIS);
  clearFlag(FLYTRAP, NDESCBIT);
  await UNDO_TRAP();
  return await DEQUEUE(I_FLYTRAP.id);
}

async function SPAWNING_GROUND_F(rarg) {
  if (rarg == M_LOOK) {
    tell("As if this hasn't already been a rough enough day, you have stumbled upon a spawning ground for Venusian slime beasts. ", S(g.OOZY_WITH_SLIME), " Fortunately, these beasts are still in the earliest (and least deadly) stage. Only one spot is free of slime:");
    await TPRINT(HOLE);
    tell(" near the path to the east.");
    return true;
  } else {
    return false;
  }
}

async function CREAM_F() {
  if (isVerb(V.EXAMINE, V.LOOK_INSIDE)) {
    return await EXAMINE_CREAM_AND_STAIN();
  } else if (isVerb(V.READ)) {
    tell("The jar is marked \"Un");
    if (!(hasFlag(CREAM, UNTEEDBIT))) {
      tell("t");
    }
    tell("angling cream.\"\n");
    return true;
  } else if (isVerb(V.EMPTY) && (g.PRSO == CREAM)) {
    if (!g.PRSI) {
      put(g.P_NAMW, 1, false);
      g.PRSI = GROUND;
    }
    if (hasFlag(CREAM, MUNGBIT)) {
      tell(S(g.ALREADY_IS));
      return true;
    } else {
      put(g.P_NAMW, 0, W.CREAM);
      await PERFORM(V.PUT_ON, CREAM, g.PRSI);
      return true;
    }
  } else if (isVerb(V.OPEN, V.CLOSE)) {
    return await NO_LID();
  } else if (isVerb(V.EAT)) {
    tell(S(g.YECHH));
    return true;
  } else if (isVerb(V.POUR, V.PUT_ON, V.RUB) && (g.PRSO == CREAM) && !(eq(get(g.P_NAMW, 0), W.JAR, false))) {
    if (hasFlag(CREAM, MUNGBIT)) {
      await EXAMINE_CREAM_AND_STAIN();
      return true;
    }
    move(CREAM, PROTAGONIST);
    setFlag(CREAM, MUNGBIT);
    tell("As the lotion soaks in,");
    if (hasFlag(CREAM, UNTEEDBIT) && (g.PRSI == THETA)) {
      move(EIGHTY_TWO_DEGREE_ANGLE, THRONE_ROOM);
      clearFlag(THETA, MUNGBIT);
      clearFlag(THETA, NDESCBIT);
      setFlag(THETA, ACTORBIT);
      setFlag(THETA, FEMALEBIT);
      setFlag(THETA, NARTICLEBIT);
      putProp(THETA, P.SDESC, "Princess Theta");
      await INCREMENT_SCORE(16, 10, true);
      tell(" the angle slowly transforms into a beautiful princess. Mitre, gushing tears of happiness, cries, \"You have restored my beloved Theta to me!\" He reveals a perfect ");
      await DPRINT(EIGHTY_TWO_DEGREE_ANGLE);
      tell(". \"I only brushed against it,\" explains the King. \"Please accept it, along with my thanks.\" He reaches out to shake ", D(HANDS), S(g.PERIOD_CR));
      return true;
    } else if ((g.PRSI == PILE_OF_ANGLES) && hasFlag(CREAM, UNTEEDBIT)) {
      return (await JIGS_UP(" the angles return to their former forms: a golden chariot, a velvet tapestry, various fruits, some handcuffs, a flock of ducks ... and a huge hungry tiger."));
    } else if (g.PRSI == ME) {
      tell(" your skin tingles a bit.\n");
      return true;
    } else {
      await TPRINT_PRSI();
      tell(" seem");
      if (!(hasFlag(g.PRSI, PLURALBIT))) {
        tell("s");
      }
      tell(" unchanged. ");
      if ((g.PRSI == MITRE) && hasFlag(CREAM, UNTEEDBIT)) {
        tell("(Like fighting a forest fire with a water pistol.)\n");
        return true;
      } else {
        tell("I guess ");
        if (hasFlag(g.PRSI, PLURALBIT)) {
          tell("they were");
        } else {
          if (hasFlag(g.PRSI, FEMALEBIT)) {
            tell("she");
          } else if (hasFlag(g.PRSI, ACTORBIT)) {
            tell("he");
          } else {
            tell("it");
          }
          tell(" was");
        }
        tell("n't very ");
        if (!(hasFlag(CREAM, UNTEEDBIT))) {
          tell("t");
        }
        tell("angled.\n");
        return true;
      }
    }
  } else {
    return false;
  }
}

async function FORK_OF_SORTS_F(rarg) {
  if ((rarg == M_ENTER) && !(hasFlag(g.HERE, TOUCHBIT)) && !(g.VERBOSITY == 0)) {
    tell("A mighty tree rises before you in the center of the path. Suddenly and without warning (as is the nature of the jungle) it dies. Within seconds, the tree is consumed by Venusian hypertermites, which then move off in search of other dead trees, leaving a massive hole in the ground.\n\n");
    return true;
  } else if (rarg == M_LOOK) {
    tell("This jungle path once split here, went around a mighty tree, and rejoined off to the east. Now, it splits here, goes around a ");
    if (g.LEAVES_PLACED) {
      printD(LEAVES);
    } else {
      tell("mighty hole");
    }
    tell(", and rejoins off to the east.");
    return true;
  } else {
    return false;
  }
}

async function TREE_HOLE_F() {
  if (isVerb(V.OPEN, V.CLOSE)) {
    tell(S(g.HUH));
    return true;
  } else if (isVerb(V.DISEMBARK) && (loc(PROTAGONIST) == TREE_HOLE)) {
    tell(S(g.YOU_CANT), "climb out. You're trapped.\n");
    return true;
  } else if (isVerb(V.REACH_IN) && (loc(FLYTRAP) == TREE_HOLE)) {
    tell("The ", D(FLYTRAP), " pulls you in. ");
    return await FLYTRAP_DEATH();
  } else if (isVerb(V.BOARD)) {
    if (hasFlag(TRELLIS, MUNGBIT)) {
      tell("The hole's covered.\n");
      return true;
    } else if (await ULTIMATELY_IN$(TRELLIS)) {
      tell(S(g.TRELLIS_TOO_WIDE));
      return true;
    } else if (loc(FLYTRAP) == TREE_HOLE) {
      tell("Hey! There's a big, hungry, angry ", D(FLYTRAP));
      return (await JIGS_UP(" down here also!"));
    } else {
      return false;
    }
  } else if (isVerb(V.MEASURE)) {
    tell("The hole is about six feet across.\n");
    return true;
  } else if (isVerb(V.WALK_AROUND)) {
    if (loc(FLYTRAP) == g.HERE) {
      tell("You circle the hole completely, with");
      await TPRINT(FLYTRAP);
      tell(" in hot pursuit.\n");
      return true;
    } else {
      return await WEE();
    }
  } else if (isVerb(V.LOOK_INSIDE) && g.LEAVES_PLACED) {
    await PERFORM(V.BOARD, TREE_HOLE);
    return true;
  } else if (isVerb(V.PUT_ON) && (g.PRSO == LEAVES) && hasFlag(TRELLIS, MUNGBIT)) {
    await PERFORM_PRSA(LEAVES, TRELLIS);
    return true;
  } else if (isVerb(V.EXAMINE) && hasFlag(TRELLIS, MUNGBIT)) {
    await DESCRIBE_TRELLIS_ON_HOLE();
    return crlf();
  } else if (isVerb(V.UNCOVER) && hasFlag(TRELLIS, MUNGBIT)) {
    await PERFORM(V.MOVE, TRELLIS);
    return true;
  } else if (isVerb(V.HIDE) && (loc(FLYTRAP) == g.HERE)) {
    await PERFORM(V.WALK_AROUND, TREE_HOLE);
    return true;
  } else {
    return false;
  }
}

