async function STAIN_F() {
  if (hasFlag(STAIN, UNTEEDBIT)) {
    return false;
  } else if (isVerb(V.EXAMINE, V.LOOK_INSIDE)) {
    return await EXAMINE_CREAM_AND_STAIN();
  } else if (isVerb(V.APPLY) && (await GLOBAL_IN$(HOLE, g.HERE))) {
    return await APPLY_STAIN(HOLE);
  } else if (isVerb(V.EMPTY) && (g.PRSO == STAIN)) {
    if (hasFlag(STAIN, MUNGBIT)) {
      return await EXAMINE_CREAM_AND_STAIN();
    } else if (!g.PRSI || (g.PRSI == GROUND || g.PRSI == CANAL_OBJECT || g.PRSI == WATER || g.PRSI == TREE_HOLE)) {
      setFlag(STAIN, MUNGBIT);
      tell("Done. What a waste of good stain!\n");
      return true;
    } else {
      return await APPLY_STAIN(g.PRSI);
    }
  } else if (isVerb(V.OPEN, V.CLOSE)) {
    return await NO_LID();
  } else if (isVerb(V.DRINK)) {
    tell(S(g.YECHH));
    return true;
  } else if (isVerb(V.POUR) && (g.PRSI == GROUND || g.PRSI == CANAL_OBJECT || g.PRSI == WATER || g.PRSI == TREE_HOLE)) {
    await PERFORM(V.EMPTY, STAIN, GROUND);
    return true;
  } else if (isVerb(V.POUR, V.PUT_ON, V.RUB) && (g.PRSO == STAIN) && (await NOUN_USED(W.STAIN, STAIN))) {
    return await APPLY_STAIN(g.PRSI);
  } else {
    return false;
  }
}

async function APPLY_STAIN(obj) {
  if (hasFlag(STAIN, MUNGBIT)) {
    g.PRSO = STAIN;
    return await EXAMINE_CREAM_AND_STAIN();
  } else if (obj == HOLE) {
    await THIS_IS_IT(HOLE);
    tell("The circle is ");
    if (await CIRCLE_ISNT_BLACK()) {
      g.CIRCLE_BLACK = true;
      setFlag(STAIN, MUNGBIT);
      put(g.P_ADJW, 0, false);
      put(g.P_ADJW, 1, false);
      putProp(HOLE, P.SDESC, "black circle");
      tell("once again");
    } else {
      tell("already");
    }
    tell(" black!\n");
    return true;
  } else if (obj == FLYTRAP) {
    await PERFORM(V.TOUCH, FLYTRAP);
    return true;
  } else {
    tell("You apply a tiny dab to");
    await TPRINT(obj);
    tell(" but it doesn't stick.\n");
    return true;
  }
}

async function EXAMINE_CREAM_AND_STAIN() {
  tell("The ");
  await DPRINT(g.PRSO);
  tell(" is ");
  if (hasFlag(g.PRSO, MUNGBIT)) {
    tell("empty");
  } else {
    tell("full");
  }
  if (isVerb(V.EXAMINE)) {
    tell(", and has some writing on it");
  }
  tell(S(g.PERIOD_CR));
  return true;
}

