async function POWER_SWITCH_F() {
  if ((await TOUCHING$(POWER_SWITCH)) && !(loc(PROTAGONIST) == g.HERE)) {
    return await CANT_REACH(POWER_SWITCH);
  } else if (isVerb(V.SET, V.ON, V.OFF, V.THROW, V.MOVE, V.PUSH, V.RAISE, V.LOWER, V.OPEN, V.CLOSE) && (g.PRSO == POWER_SWITCH)) {
    if (loc(MAD_SCIENTIST) == g.HERE) {
      tell("The ", D(MAD_SCIENTIST), " stops you.\n");
      return true;
    } else {
      await IDENTITY_TRANSFER();
      tell("Zap! You're back in ");
      if (g.GONE_APE) {
        tell("the body of the ");
        if (!g.MALE) {
          tell("fe");
        }
        tell(D(MALE_GORILLA), ".");
      } else {
        if (!(hasFlag(RUBBER_HOSE, MUNGBIT))) {
          setFlag(RUBBER_HOSE, MUNGBIT);
          await INCREMENT_SCORE(19, 24, true);
        }
        move(MALE_GORILLA, CAGE);
        move(FEMALE_GORILLA, CAGE);
        tell("your own body! The gorilla looks confused and slinks back into the comfortingly familiar environment of the cage.");
      }
      if (g.BODY_TIED_TO_SLAB && !g.SIDEKICKS_BODY_TIED_TO_SLAB && (await VISIBLE$(SIDEKICK))) {
        g.BODY_TIED_TO_SLAB = false;
        move(SIDEKICK, g.HERE);
        tell(" ");
        await DPRINT_SIDEKICK();
        tell(" rushes over and unties you.");
      }
      return crlf();
    }
  } else {
    return false;
  }
}

async function IDENTITY_TRANSFER() {
  await OPEN_EYES_AND_REMOVE_HANDS();
  if (g.GONE_APE) {
    if (g.MALE) {
      await ROB(PROTAGONIST, MALE_GORILLA);
      move(MALE_GORILLA, loc(PROTAGONIST));
      clearFlag(MALE_GORILLA, NDESCBIT);
    } else {
      await ROB(PROTAGONIST, FEMALE_GORILLA);
      move(FEMALE_GORILLA, loc(PROTAGONIST));
      clearFlag(FEMALE_GORILLA, NDESCBIT);
    }
    if (await VISIBLE$(SIDEKICKS_BODY)) {
      move(SIDEKICK, loc(SIDEKICKS_BODY));
      remove(SIDEKICKS_BODY);
    }
    move(PROTAGONIST, loc(YOUR_BODY));
    await ROB(YOUR_BODY, PROTAGONIST);
    remove(YOUR_BODY);
    return g.GONE_APE = false;
  } else {
    g.GONE_APE = true;
    move(YOUR_BODY, loc(PROTAGONIST));
    await ROB(PROTAGONIST, YOUR_BODY);
    if (g.MALE) {
      move(PROTAGONIST, loc(MALE_GORILLA));
      setFlag(MALE_GORILLA, NDESCBIT);
      await ROB(MALE_GORILLA, PROTAGONIST);
    } else {
      move(PROTAGONIST, loc(FEMALE_GORILLA));
      setFlag(FEMALE_GORILLA, NDESCBIT);
      await ROB(FEMALE_GORILLA, PROTAGONIST);
    }
    if (await VISIBLE$(SIDEKICK)) {
      move(SIDEKICKS_BODY, loc(SIDEKICK));
      return remove(SIDEKICK);
    } else {
      return false;
    }
  }
}

