async function CAGE_F() {
  if (isVerb(V.EXAMINE)) {
    tell("The bars ");
    if (hasFlag(CAGE, MUNGBIT)) {
      tell("have been", S(g.SPREAD_APART));
    } else {
      tell("seem sturdy");
    }
    tell(S(g.PERIOD_CR));
    return true;
  } else if (isVerb(V.ENTER, V.BOARD, V.WALK_TO, V.DISEMBARK, V.LEAVE, V.EXIT) && (g.HERE == LABORATORY) && !(hasFlag(CAGE, MUNGBIT))) {
    tell("You don't fit between the bars.\n");
    return true;
  } else if (isVerb(V.OPEN, V.MUNG, V.BEND) || (isVerb(V.MOVE) && !(await NOUN_USED(W.CAGE, CAGE)))) {
    if (hasFlag(CAGE, MUNGBIT)) {
      tell(S(g.SENILITY_STRIKES));
      return true;
    } else if (!g.GONE_APE) {
      tell("This cage was built to hold an ape! Mere human strength is nothing against these bars!\n");
      return true;
    } else {
      tell("Bellowing madly, you pull at the bars! ");
      if (g.SUGAR_RUSH == GORILLA_ATE_CHOCOLATE) {
        setFlag(CAGE, MUNGBIT);
        tell("Slowly, they", S(g.SPREAD_APART), ".");
        if (loc(MAD_SCIENTIST) == g.HERE) {
          tell(" The ", D(MAD_SCIENTIST));
          return (await JIGS_UP(" yells, \"Mein Gott! Mad gorilla on der loose!\" He pulls out a ray gun and puts a bolt through your chest."));
        } else {
          return crlf();
        }
      } else {
        tell("They almost give, but you haven't got quite enough strength.\n");
        return true;
      }
    }
  } else if (isVerb(V.PUT) && (g.PRSI == CAGE) && eq(loc(PROTAGONIST), FIRST_SLAB, SECOND_SLAB)) {
    return await CANT_REACH(CAGE);
  } else if (isVerb(V.REACH_IN)) {
    if (loc(PROTAGONIST) == CAGE) {
      tell(S(g.LOOK_AROUND));
      return true;
    } else if (loc(RUBBER_HOSE) == CAGE) {
      return await CANT_REACH(RUBBER_HOSE);
    } else {
      return false;
    }
  } else {
    return false;
  }
}

async function GORILLA_F() {
  if (g.GONE_APE && g.MALE && (g.PRSO == MALE_GORILLA)) {
    await PERFORM_PRSA(ME, g.PRSI);
    return true;
  } else if (g.GONE_APE && g.MALE && (g.PRSI == MALE_GORILLA)) {
    await PERFORM_PRSA(g.PRSO, ME);
    return true;
  } else if (g.GONE_APE && !g.MALE && (g.PRSO == FEMALE_GORILLA)) {
    await PERFORM_PRSA(ME, g.PRSI);
    return true;
  } else if (g.GONE_APE && !g.MALE && (g.PRSI == FEMALE_GORILLA)) {
    await PERFORM_PRSA(g.PRSO, ME);
    return true;
  } else if (isVerb(V.TELL)) {
    tell("\"Ooo oo ee ee ee!\"\n");
    return await STOP();
  } else if (isVerb(V.GIVE) && (g.PRSI == MALE_GORILLA || g.PRSI == FEMALE_GORILLA)) {
    if (eq(loc(PROTAGONIST), FIRST_SLAB, SECOND_SLAB)) {
      return await CANT_REACH(g.PRSI);
    } else {
      await EAGERLY_ACCEPTS();
      tell(S(g.PERIOD_CR));
      return true;
    }
  } else if (isVerb(V.EXAMINE)) {
    if (g.GONE_APE) {
      g.GORILLA_EXAMINED = true;
      await NOT_BAD_LOOKING();
    } else {
      tell("An uglier beast cannot possibly exist.");
    }
    if (first(g.PRSO)) {
      tell(" ");
      return false;
    } else {
      return crlf();
    }
  } else if (isVerb(V.FUCK, V.KISS, V.TOUCH)) {
    if (!g.GONE_APE) {
      tell("What a repulsive, bestial idea!\n");
      return true;
    } else {
      if (g.NAUGHTY_LEVEL == 0) {
        tell("Normally, we wouldn't allow this in TAME mode, but it's okay in this case since you're only a gorilla. This sort of thing appears all the time in National Geographic.");
      } else {
        if (!g.GORILLA_EXAMINED) {
          g.GORILLA_EXAMINED = true;
          await NOT_BAD_LOOKING();
          tell(" ");
        }
        tell("You begin nuzzling, and things quickly get hot and heavy.");
        if (g.NAUGHTY_LEVEL == 2) {
          tell(" The ", D(g.PRSO), " screams, \"Eee oo oo ah!\" which translates roughly as \"Oh, you animal!\"");
        }
      }
      if (loc(MAD_SCIENTIST) == g.HERE) {
        tell(" ");
        return await MINE_THEORY(true);
      } else {
        return crlf();
      }
    }
  } else {
    return false;
  }
}

