async function MINE_THEORY(right = false) {
  remove(MAD_SCIENTIST);
  await DEQUEUE(I_MAD_SCIENTIST.id);
  g.FOLLOW_FLAG = 17;
  await QUEUE(I_FOLLOW.id, 2);
  tell("\"Ach!\" yells");
  await TPRINT(MAD_SCIENTIST);
  tell(", \"mein theory iss ");
  if (right) {
    tell("correct");
  } else {
    tell("wronk");
  }
  tell("! Der sex drive uf a species resides in der b");
  if (right) {
    tell("ody");
  } else {
    tell("rain");
  }
  tell(", not in der b");
  if (right) {
    tell("rain");
  } else {
    tell("ody");
  }
  tell("!\" He dashes off.\n");
  if (await VISIBLE$(SIDEKICKS_BODY)) {
    tell("   Through the briefly open door, you see two ", D(FLYTRAP), "s running madly around the next room. One is chasing, while the other is frantically trying to stay as far away as possible.\n");
  }
  return true;
}

