async function LEAVES_F() {
  if (isVerb(V.ENTER)) {
    if (await ULTIMATELY_IN$(LEAVES)) {
      tell(S(g.HOLDING_IT));
      return true;
    } else {
      return await WEE();
    }
  } else if (isVerb(V.TAKE)) {
    if (await PRE_TOUCH()) {
      return true;
    }
    tell(S(g.YOU_CANT), "hold so many leaves in your arms!\n");
    return true;
  } else if (isVerb(V.RAKE)) {
    tell("They're already in a ");
    if (loc(LEAVES) == SACK) {
      printD(SACK);
    } else {
      tell("pile");
    }
    tell(S(g.PERIOD_CR));
    return true;
  } else if (isVerb(V.COUNT)) {
    tell("69,105.\n");
    return true;
  } else if (isVerb(V.SEARCH, V.LOOK_INSIDE)) {
    tell("You find ... more leaves!\n");
    return true;
  } else if (isVerb(V.POUR) && (g.PRSO == LEAVES)) {
    if (await ULTIMATELY_IN$(LEAVES)) {
      if (g.PRSI == WINDOW) {
        await PERFORM(V.PUT_THROUGH, LEAVES, WINDOW);
        return true;
      } else {
        await PERFORM(V.PUT, LEAVES, g.PRSI);
        return true;
      }
    } else {
      tell(S(g.YNH));
      await TRPRINT(LEAVES);
      return true;
    }
  } else if ((isVerb(V.PUSH, V.PUT) && (g.PRSI == SACK)) || (isVerb(V.FILL) && (g.PRSO == SACK))) {
    if (await UNTOUCHABLE$(LEAVES)) {
      await CANT_REACH(LEAVES);
      return true;
    } else if (loc(LEAVES) == SACK) {
      return false;
    }
    clearFlag(LEAVES, TRYTAKEBIT);
    g.LEAVES_PLACED = false;
    setFlag(TREE_HOLE, OPENBIT);
    clearFlag(LEAVES, NDESCBIT);
    move(LEAVES, SACK);
    tell("Done.\n");
    return true;
  } else if (isVerb(V.MOVE) && g.LEAVES_PLACED) {
    clearFlag(LEAVES, TRYTAKEBIT);
    g.LEAVES_PLACED = false;
    setFlag(TREE_HOLE, OPENBIT);
    clearFlag(LEAVES, NDESCBIT);
    move(LEAVES, g.HERE);
    tell("You uncover the trellis.\n");
    return true;
  } else if (isVerb(V.LOOK_UNDER) && g.LEAVES_PLACED) {
    await TRELLIS_VISIBLE();
    return crlf();
  } else if (isVerb(V.EMPTY) && (g.PRSO == LEAVES) && (loc(LEAVES) == SACK)) {
    await PERFORM(V.DROP, LEAVES);
    return true;
  } else if (isVerb(V.STAND_ON, V.CLIMB_ON, V.BOARD) && g.LEAVES_PLACED) {
    await PERFORM(V.STAND_ON, TRELLIS);
    return true;
  } else {
    return false;
  }
}

