async function I_BOUDOIR(not_called_by_fuck = true) {
  tell("   You hear a click, and ");
  if (!(loc(PROTAGONIST) == g.HERE)) {
    tell("leap to your feet as ");
  }
  tell("the room is flooded with light!\n\n", D(g.HERE), "\n   Oh, no! You have violated the sanctity of a boudoir! And not just any old boudoir, but an", S(g.PRIVATE_BOUDOIR), "! And not just any old", S(g.PRIVATE_BOUDOIR), ", but an", S(g.PRIVATE_BOUDOIR), " belonging to ", D(LGOP), "!\n   \"The escaped prisoner");
  if (await VISIBLE$(SIDEKICK)) {
    tell("s");
  }
  tell("!\" cries one of ", D(LGOP), ". \"Sound the alarm!\"\n   \"Inform the guards!\" yells another.\n   \"Call out the army!\"\n   \"Alert the space fleet!\"\n   \"Summon my masseur,\" says the single unfrantic Goddess, calmly pulling a lever. As the floor opens up, you");
  await AND_SIDEKICK();
  tell(" plunge down a long chute", S(g.ELLIPSIS));
  await INCREMENT_SCORE(9, 13);
  await GOTO(PLAZA, true);
  if (await ULTIMATELY_IN$(SIDEKICK, BOUDOIR)) {
    move(SIDEKICK, PLAZA);
  }
  if (not_called_by_fuck && !(isVerb(V.WAIT))) {
    await PLAZA_F(M_END);
  }
  return true;
}

async function LGOP_F() {
  if (LGOP == g.WINNER) {
    if (isVerb(V.KISS) && (g.PRSO == ME)) {
      g.WINNER = PROTAGONIST;
      await PERFORM_PRSA(LGOP);
      g.WINNER = LGOP;
      return true;
    } else if (isVerb(V.FUCK, V.TAKE) && (g.PRSO == ME)) {
      g.WINNER = PROTAGONIST;
      await PERFORM(V.FUCK, LGOP);
      g.WINNER = LGOP;
      return true;
    } else if (g.NAUGHTY_LEVEL == 0) {
      tell(S(g.LEAVE_ME_ALONE));
      return true;
    } else {
      tell("\"Shut up and kiss me, honey.\"\n");
      return await STOP();
    }
  } else if (isVerb(V.EXAMINE)) {
    tell("The lighting is too dim to see more than vague shapes.");
    if (!(g.NAUGHTY_LEVEL == 0)) {
      tell(" But very shapely shapes!");
    }
    return crlf();
  } else if (isVerb(V.TOUCH, V.FUCK, V.KISS) && (g.NAUGHTY_LEVEL == 0)) {
    tell("You're pushed away. ", S(g.LEAVE_ME_ALONE));
    return true;
  } else if (isVerb(V.EAT)) {
    if (g.NAUGHTY_LEVEL == 0) {
      return await V_FUCK();
    } else if (g.NAUGHTY_LEVEL == 1) {
      tell(S(g.MISSIONARY_ONLY));
      return true;
    } else {
      tell("As you dive between her thighs, she arches toward you, shivering with hedonistic pleasure.\n");
      return true;
    }
  } else if (isVerb(V.TOUCH)) {
    tell("Your arms discover a soft and eager body. You hear a purr of pleasure");
    if (g.NAUGHTY_LEVEL == 2) {
      (await BODIES_PRESS_TOGETHER("fondling", "breasts"));
    }
    tell(S(g.PERIOD_CR));
    return true;
  } else if (isVerb(V.KISS)) {
    tell("Your lips meet those of your couchmate -- full, moist lips; the lips of someone who knows how to kiss");
    if (g.NAUGHTY_LEVEL == 2) {
      tell(". A tongue slides teasingly into ", D(MOUTH));
      (await BODIES_PRESS_TOGETHER("kissing", "lips"));
    }
    if (await VISIBLE$(SIDEKICK)) {
      tell(S(g.PERIOD_CR), "   You hear a \"thunk\" as ");
      await DPRINT_SIDEKICK();
      tell(", humping enthusiastically, falls off ");
      await HIS_HER();
      tell(" couch");
    }
    tell(S(g.PERIOD_CR));
    return true;
  } else if (isVerb(V.SMELL)) {
    await PERFORM_PRSA(ODOR);
    return true;
  } else if (isVerb(V.FUCK)) {
    tell("Your couchmate seems only too happy to oblige. You flush with passion");
    if (g.NAUGHTY_LEVEL == 2) {
      (await BODIES_PRESS_TOGETHER("making love to", "breasts"));
    }
    tell(". Suddenly...\n");
    await DEQUEUE(I_BOUDOIR.id);
    return await I_BOUDOIR(false);
  } else {
    return false;
  }
}

async function BODIES_PRESS_TOGETHER(verb_string, noun_string) {
  move(PROTAGONIST, DIVAN);
  tell(" as your two bodies draw closer together on the divan");
  if (!g.MALE && !g.DISCOVERED) {
    g.DISCOVERED = true;
    tell(". You discover, much to your surprise, that you are ", S(verb_string), " a woman. Even more surprising, your misgivings are swept away by the heady pleasure of the soft, full ", S(noun_string), " pressing against your own");
    return true;
  } else {
    return false;
  }
}

async function PLAZA_F(rarg) {
  if (rarg == M_LOOK) {
    tell("This is a wide plaza between", S(g.PLEASURE_PALACE_DESC), D(LGOP), ". It is a lovely, bucolic area of gushing fountains, curving flower beds, and lawns of thick, green grass. Birds fly amongst the trees, singing peacefully, as baby squirrels hop across the lawn, lazily collecting nuts.");
    return true;
  } else if (rarg == M_SMELL) {
    tell("Through the smoke of battle, you see a banana peel squirt from");
    await TPRINT(ANTI_LGOP_MACHINE);
    tell(".");
    return true;
  } else if (rarg == M_END) {
    g.PLAZA_COUNTER = g.PLAZA_COUNTER + 1;
    tell("   ");
    if (g.PLAZA_COUNTER == 1) {
      tell("A half-megaton grenade explodes nearby as the palace guards attempt to repel ");
      if (loc(SIDEKICK) == g.HERE) {
        tell("some");
      } else {
        tell("an");
      }
      tell(" unwanted intruder");
      if (loc(SIDEKICK) == g.HERE) {
        tell("s");
      }
      tell(" (namely: you");
      await AND_SIDEKICK();
      tell(").\n");
    } else if (g.PLAZA_COUNTER == 2) {
      tell("The guards now have reinforcements: a row of imposing radium-powered tanks are rolling towards you.\n");
    } else if (g.PLAZA_COUNTER == 3) {
      tell("Giant berserk robotoid sumo wrestlers, each madly waving about three dozen samurai swords, are now storming across the plaza at you.\n");
    } else if (g.PLAZA_COUNTER == 4) {
      tell("With a swooping roar, the", S(g.ATTACK_FLEET), " of ", D(LGOP), " joins the attack. Several nearby trees are suddenly vaporized.\n");
    } else if (g.PLAZA_COUNTER == 5) {
      tell("The palace guards are setting up a massive dematerialization ray. Closer by, a sumo-robot discovers a boulder in its path, and a large quantity of gravel is created.\n");
    } else if (g.PLAZA_COUNTER == 6) {
      tell("A Phobosian Chomper is faster than a cheetah, meaner than a Tyrannosaurus Rex, bigger than a sperm whale, and as hungry as the state of Texas. We mention this because fifty of them just entered the plaza and spotted you.\n");
    } else if (g.PLAZA_COUNTER == 7) {
      tell("Several fifty-foot craters appear as the", S(g.ATTACK_FLEET), " begins lobbing ion bombs. As they veer around for a more precise attack, the tanks close in, and you realize that each one is larger than the Upper Sandusky City Hall.\n");
    } else if (g.PLAZA_COUNTER == 8) {
      tell("A couple of buildings behind you silently vanish, indicating that the palace guards are better at assembling a death ray than at aiming it. However, in sixty centuries of repelling intruders, they've never missed twice. Meanwhile, one of the Chompers has stopped to swallow a herd of goats that was grazing nearby, thus slowing it down for a full tenth of a second.\n");
    } else if (g.PLAZA_COUNTER == 9) {
      tell("The guards have finished aiming the death ray, and have begun the activation sequence. The ground quakes as the berserko robotoids plow through the rubble toward you; the wind from their whirling swords knocks over a few trees. The tanks loom above you, their gun turrets blocking out the sun. Beyond them, the", S(g.ATTACK_FLEET), " is sweeping in for a final attack.\n");
    } else if (g.PLAZA_COUNTER == 10) {
      (await JIGS_UP("All your attackers come together in a climactic battle scene far too incredible to describe in the 23 words allotted to this sentence."));
    }
    if (!(await VISIBLE$(SIDEKICK))) {
      return true;
    }
    tell("   ");
    await DPRINT_SIDEKICK();
    if (g.PLAZA_COUNTER == 1) {
      move(ANTI_LGOP_MACHINE, g.HERE);
      tell(" shouts, \"Okay, this is it!");
      if (first(SIDEKICK)) {
        await ROB(SIDEKICK, PROTAGONIST);
        tell("\" ");
        await HE_SHE(true);
        tell(" hands you everything ");
        await HE_SHE();
        tell("'s carrying. \"");
      } else {
        tell(" ");
      }
      tell("Gotta start building that ", D(ANTI_LGOP_MACHINE), "! ");
    } else {
      tell(", hammering and twiddling madly at the growing machine, yells, \"");
      if (g.RIGHT_PART) {
        tell("Okay, things are going ", S(get(g.HYPE_WORD, g.PLAZA_COUNTER - 2)), "! ");
      } else {
        g.MISSING_PART = get(g.PARTS_LIST, g.PLAZA_COUNTER - 2);
        tell("Well, I'll try and work around the missing ");
        if (g.MISSING_PART == PHOTO) {
          tell(S(getProp(PHOTO, P.SDESC)));
        } else {
          printD(g.MISSING_PART);
        }
        tell(". ");
      }
      if (g.PLAZA_COUNTER == 9) {
        tell("There! I think it's all done. Cross your fingers, kiddo!\" ");
        await HE_SHE(true);
        tell(" switches on the device. Amidst showers of sparks, a powerful electric arc bridges two electrodes. The machine shudders, and ");
        if (g.MISSING_PART) {
          tell("awe-inspiring rays of raw plasma begin shooting in every direction. You and ");
          await DPRINT_SIDEKICK();
          tell(" dive to the ground. Crashing spaceships collide with careening robotoid monsters; the tanks, inches before pancaking you, become pools of molten metal. A stray plasma ray strikes the only remaining tree in the plaza, and you are fatally wounded as a coconut drops onto ", D(HEAD), ". The last sound you hear is ");
          await DPRINT_SIDEKICK();
          tell("'s voice, saying,");
          await EXPLETIVE();
          tell("I was going to use that ");
          if (g.MISSING_PART == PHOTO) {
            tell(S(getProp(PHOTO, P.SDESC)));
          } else {
            printD(g.MISSING_PART);
          }
          tell(" to build a coconut deflector.\"\n");
        } else {
          tell("you ");
          if (hasFlag(NOSE, MUNGBIT)) {
            tell("see");
          } else {
            tell("smell");
          }
          tell(" something yellow shoot from the machine.");
          if (hasFlag(NOSE, MUNGBIT)) {
            tell(" It's a banana peel!\n");
          } else {
            crlf();
            await PERFORM(V.SMELL, ODOR);
          }
          tell("   The peel lands a few feet away, as the ", D(ANTI_LGOP_MACHINE), " gives one final shudder and self-destructs in an orgy of flames and shrapnel!\n   The attacking forces continue to close, and certain death is only seconds away when one of the Chompers, loping toward you at nearly Mach One, steps on the banana peel, and slips a few inches to one side before righting itself. This is enough, however, to nudge a tank into a crater, tripping one of the samurai robots!\n   More and more of the attacking forces plow into the mess in the crater, like some improbably fantastical football tackle. A stray grenade lands right in its midst, and the resulting plume of debris shears the fins off the leading warship. Your heart leaps as the entire", S(g.ATTACK_FLEET), " of ", D(LGOP), " plummets toward the ground. The mass of flaming metal strikes the ground, and a tremendous explosion knocks you senseless!\n\n   Eventually, daylight intrudes upon your senselessness and illuminates a sleepy-looking gas station. You are lying at the edge of a dusty road, once again wearing your comfortable old overalls. Though dirty, dishevelled, and bleeding from a few superficial cuts, you are nevertheless aglow in the knowledge that Earth is safe from the threat of ", D(LGOP), ".\n   As ", D(HEAD), " clears, three uniformed ");
          if (g.MALE) {
            tell("girls come bounc");
          } else {
            tell("guys come pound");
          }
          tell("ing out of the service station toward you. \"Oh, my goodness,\" they ");
          if (g.MALE) {
            tell("coo");
          } else {
            tell("call out");
          }
          tell(", in perfect unison. \"Are you all right?\"\n\n   Coming soon from Infocom: GAS PUMP GIRLS MEET THE PULSATING INCONVENIENCE FROM PLANET X.\n");
          g.RANK = 9;
          g.EXT_MAX = g.INT_MAX;
        }
        await FINISH();
      }
    }
    tell("Hand me a");
    await PRINT_PART();
    tell(".\"\n");
    g.RIGHT_PART = false;
    return await THIS_IS_IT(SIDEKICK);
  } else {
    return false;
  }
}

async function PRINT_PART() {
  let next_part = 0;
  next_part = get(g.PARTS_LIST, g.PLAZA_COUNTER - 1);
  await THIS_IS_IT(next_part);
  if (next_part == EIGHTY_TWO_DEGREE_ANGLE) {
    tell("n ");
  } else {
    tell(" ");
  }
  if (next_part == PHOTO) {
    tell(S(getProp(PHOTO, P.SDESC)));
    return true;
  } else {
    return printD(next_part);
  }
}

async function GENERIC_MACHINE_F() {
  let num = 0;
  num = await CANAL_LOC();
  if ((g.HERE == CANAL) && ((num > 31) || (num < 13))) {
    return ODD_MACHINE;
  } else if (isVerb(V.ASK_ABOUT)) {
    if (await VISIBLE$(ODD_MACHINE)) {
      return ODD_MACHINE;
    } else {
      return ANTI_LGOP_MACHINE;
    }
  } else if ((SIDEKICK == g.WINNER) && !(await QUEUED$(I_BLUEPRINT.id))) {
    return ANTI_LGOP_MACHINE;
  } else {
    return false;
  }
}

